// Texture group enumeration and gating.
// Generated by texture_pipeline.py 'targets' step.
// Do not edit manually; changes will be overwritten.
#pragma once

namespace texgroups {
enum Group : int {
    Hands   = 0,   // in-view gloves / hands
    Weapons = 1,   // first-person weapon meshes
    Enemies = 2,   // enemy character / boss textures
    Env     = 3,   // environment surfaces (doors, walls, floors)
    Glyphs  = 4,   // UI / button prompt glyphs
    FX      = 5,   // muzzle flash, explosions, particles
    GCount  = 6
};

inline const char* GroupName(int g) {
    static const char* names[GCount] = {
        "Hands", "Weapons", "Enemies", "Env", "Glyphs", "FX"
    };
    return (g >= 0 && g < GCount) ? names[g] : "Unknown";
}

inline int GroupIndex(const char* ddsName) {
    // Simple prefix-based classification; can be extended to use manifest mapping.
    if (!ddsName) return -1;
    if (strncmp(ddsName, "inview_glove", 12) == 0) return Hands;
    if (strncmp(ddsName, "handgun", 7) == 0) return Weapons;
    if (strncmp(ddsName, "AR_", 3) == 0 || strncmp(ddsName, "ar_", 3) == 0) return Weapons;
    if (strncmp(ddsName, "shotgun", 7) == 0) return Weapons;
    if (strncmp(ddsName, "laser_", 6) == 0) return Weapons;
    if (strncmp(ddsName, "Spetsnaz", 8) == 0) return Enemies;
    if (strncmp(ddsName, "PhaseTick", 9) == 0) return Enemies;
    if (strncmp(ddsName, "Revert", 6) == 0) return Enemies;
    if (strncmp(ddsName, "elite_", 6) == 0) return Enemies;
    if (strncmp(ddsName, "env_", 4) == 0) return Env;
    if (strncmp(ddsName, "door_", 5) == 0) return Env;
    if (strncmp(ddsName, "env_", 4) == 0) return Env;
    if (strncmp(ddsName, "shutter", 7) == 0) return Env;
    if (strncmp(ddsName, "brightFlash", 11) == 0) return FX;
    if (strncmp(ddsName, "bsplat", 6) == 0) return FX;
    if (strncmp(ddsName, "explosion", 9) == 0) return FX;
    if (strncmp(ddsName, "fireball", 8) == 0) return FX;
    if (strncmp(ddsName, "muzzleFlash", 11) == 0) return FX;
    if (strncmp(ddsName, "muzzleflash", 11) == 0) return FX;
    if (strncmp(ddsName, "crosshair", 9) == 0) return Glyphs;
    if (strncmp(ddsName, "button_", 7) == 0) return Glyphs;
    if (strncmp(ddsName, "glyph_", 6) == 0) return Glyphs;
    if (strncmp(ddsName, "prompt_", 7) == 0) return Glyphs;
    return -1; // unclassified -> not gated
}

inline bool GroupAllows(bool enabled[GCount], int groupIdx) {
    if (groupIdx < 0) return true; // unclassified always allowed
    return enabled[groupIdx];
}

// Quality tier suffix for replacement filenames.
// 2x -> "__A_lanczos" or "__B_ibp" (variant-specific, handled in build.ps1)
// 4K -> "_4K"
// 8K -> "_8K"
inline const char* QualitySuffix(const char* quality) {
    if (!quality) return "_2x";
    if (strcmp(quality, "4K") == 0) return "_4K";
    if (strcmp(quality, "8K") == 0) return "_8K";
    return "_2x"; // default "2x"
}
}